INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-56-UND-01', 'English Literacy', 'understanding', '5-6', 'standard', '"The fennec fox remains sequestered subterraneanly throughout the blistering daylight hours, emerging only when twilight cools the Sahara dunes." What behavioral adaptation is described in this passage?', '[{"text":"Hunting diurnal desert rodents that only sleep when darkness falls.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Nocturnal behavior engineered to conserve internal moisture and avoid intense daytime heat.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Impaired eyesight that functions exclusively in dim twilight illumination.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Seasonal migration toward coastal salt marshes during peak summer.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting ecological adaptations and descriptive vocabulary in informational prose.', 'Consider why an animal would stay underground during daylight and come out at twilight.', 1.15, -0.7, 0.25, true, 0, 'Singapore Primary 5 English / MOE PSLE Preparation'),
('ENG-56-UND-02', 'English Literacy', 'understanding', '5-6', 'standard', '"The apprentice blacksmith watched the glowing iron bar slowly fade from brilliant orange to a sullen charcoal gray, realizing his window to hammer the blade had closed." What does "window" mean in this sentence?', '[{"text":"A limited opportunity or timeframe to shape the metal while it remained sufficiently malleable.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A glass pane set in the forge wall to vent toxic coal smoke.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A carved aperture through which the master smith evaluated work.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A measurement of the physical length of the cooling anvil.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deducing contextual and figurative word meanings from narrative context.', 'Think about what closes when metal cools down and becomes too hard to strike.', 1.2, -0.6, 0.25, true, 0, 'Cambridge Primary Stage 5 Checkpoint'),
('ENG-56-UND-03', 'English Literacy', 'understanding', '5-6', 'standard', '"The old botanist spoke of the rainforest canopy not as a passive ceiling of leaves, but as a dynamic emerald battlefield where vines and saplings wrestled incessantly for every ray of sunlight." What central impression does this passage convey?', '[{"text":"The quiet serenity and complete harmony of an untouched tropical ecosystem.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Intense, ongoing competition among plant species for vital solar energy.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"The damage caused by human lumber companies felling ancient trees.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The poisonous nature of creeping vines on the forest floor.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing metaphor and authorial conception of ecological dynamics.', 'Notice the words "battlefield", "wrestled", and "competition for sunlight".', 1.25, -0.5, 0.25, true, 0, 'US Common Core Grade 5 Informational Text'),
('ENG-56-UND-04', 'English Literacy', 'understanding', '5-6', 'standard', '"Elena stood at the crossroads. To the left lay the well-worn cobblestones of her village; to the right, an overgrown path vanished into the mist. She checked her compass, adjusted her rucksack, and stepped firmly to the right." What does Elena''s decision reveal about her character?', '[{"text":"Courage, self-reliance, and a deliberate willingness to embrace uncertain adventures.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Foolishness and an inability to read a standard magnetic compass.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A deep hatred for cobblestones and village life.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Regret over leaving behind her childhood friends.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring character archetypes and traits from symbolic choices.', 'She took the unknown overgrown path deliberately after checking her tools.', 1.3, -0.4, 0.25, true, 0, 'PIRLS Grade 5 Reading Literary Experience'),
('ENG-56-UND-05', 'English Literacy', 'understanding', '5-6', 'standard', '"In honeybee colonies, the waggle dance is not random twitching; it is a sophisticated spatial compass that encodes the precise angle relative to the sun and the distance to nectar sources." What is the main idea of this excerpt?', '[{"text":"The sun''s ultraviolet radiation damages the nervous system of worker bees.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Bees dance purely to celebrate the arrival of springtime flowers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Honeybee waggle dances serve as an intricate symbolic system for communicating food locations.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Honeybees rely entirely on scent trails rather than visual communication.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Summarizing key scientific concepts and functional animal behavior.', 'Focus on what the waggle dance communicates: angle and distance to food.', 1.2, -0.5, 0.25, true, 0, 'CBSE / ICSE Class 5 English'),
('ENG-56-UND-06', 'English Literacy', 'understanding', '5-6', 'advanced', '"The museum conservator scrutinized the painting under ultraviolet light, discovering that beneath the tranquil landscape lay an agitated, unfinished self-portrait of the artist." What does this revelation imply about the artist''s process?', '[{"text":"The painting had been created by two rival artists fighting over one easel.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The artist reused canvas, deliberately concealing an earlier intense personal work under a calm exterior.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Ultraviolet rays chemically altered the colors of the original oil paint.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The artist forgot how to paint landscapes and switched to portraits.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring hidden artistic intentionality from physical forensic evidence.', 'Why would someone paint a peaceful scene right over an agitated self-portrait?', 1.35, -0.2, 0.25, true, 0, 'Singapore Primary 6 PSLE Foundation'),
('ENG-56-UND-07', 'English Literacy', 'understanding', '5-6', 'advanced', '"The silence that fell over the debate hall was not passive indifference; it was the tense, breathless pause of a jury weighing an irrevocable verdict." What does this comparison convey about the audience?', '[{"text":"They were exhausted and preparing to leave before the speaker finished.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They were deeply engaged, captivated, and conscious of the heavy consequence of the argument.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"They were legally obligated to deliver a criminal court sentence.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They were confused by the technical jargon used by the speaker.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing psychological tension and atmosphere created through metaphor.', 'Notice the contrast: not "passive indifference", but weighing an "irrevocable verdict".', 1.4, 0, 0.25, true, 0, 'Cambridge Secondary 1 Checkpoint Stage 6'),
('ENG-56-UND-08', 'English Literacy', 'understanding', '5-6', 'advanced', '"To Marcus, the laboratory was less a sterile room of test tubes and more an alchemist''s sanctuary, where common minerals were coaxed into shedding their mundane secrets." What does the author suggest about Marcus''s perspective on science?', '[{"text":"He views scientific research as an imaginative, almost magical pursuit of fundamental truth.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"He rejects modern chemistry in favor of fraudulent medieval superstitions.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"He finds laboratory safety protocols tedious and counterproductive.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"He is primarily interested in transmuting lead into marketable gold jewelry.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing character worldview and intellectual temperament.', 'Notice terms like "sanctuary", "coaxed", and "shedding mundane secrets".', 1.35, 0.1, 0.25, true, 0, 'US Common Core Grade 6 Literature'),
('ENG-56-UND-09', 'English Literacy', 'understanding', '5-6', 'olympiad', '"The ancient aqueduct straddling the valley stood as a monument not merely to Roman hydraulic engineering, but to an unyielding refusal to let topography dictate civic ambition." What philosophical assertion underlies this statement?', '[{"text":"Roman builders prioritized ornamental stone architecture above practical water delivery.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Human determination and civil engineering can overcome severe natural geographical barriers to serve society.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Natural valleys are inherently hostile environments that must be demolished.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Aqueducts are ecologically destructive monuments that disrupt river currents.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting philosophical subtext in historical architecture commentary.', 'Notice: refusal to let "topography dictate civic ambition".', 1.5, 0.3, 0.25, true, 0, 'Singapore Primary English Olympiad / PSLE High Distinction'),
('ENG-56-UND-10', 'English Literacy', 'understanding', '5-6', 'olympiad', '"The critic noted that while the young pianist possessed flawless mechanical dexterity, her performance lacked the tender vulnerability of an artist who has known genuine grief." What shortcoming does the critic pinpoint?', '[{"text":"Poor choice of classical repertoire for an international audience.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Inaccurate timing and frequent missed notes in complex musical cadenzas.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Inadequate physical hand stamina during extended concerto movements.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Emotional depth and expressive authenticity, despite having perfect technical finger accuracy.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Differentiating between technical proficiency and expressive emotional artistry.', 'Contrast "flawless mechanical dexterity" with "lacked tender vulnerability".', 1.55, 0.4, 0.25, true, 0, 'Cambridge Checkpoint Stage 6 Olympiad Stream'),
('ENG-56-LOC-01', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Robotics Expo Guide: "Pavilion Alpha (Hall 1): Autonomous Drones; Pavilion Beta (Hall 3): Surgical Nanobots; Pavilion Gamma (Hall 4): Biomimetic Prosthetics. Keynote Address occurs in the Central Amphitheatre at 11:15 AM." Where can a visitor view surgical nanobots?', '[{"text":"Central Amphitheatre","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Pavilion Alpha in Hall 1","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Pavilion Gamma in Hall 4","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Pavilion Beta in Hall 3","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning technical conference guides for precise location identifiers.', 'Match "Surgical Nanobots" with its exact Pavilion and Hall designation.', 1.2, -0.8, 0.25, true, 0, 'PIRLS Grade 5 Factual Scanning'),
('ENG-56-LOC-02', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Space Probe Telemetry: "Probe Voyager-Prime crossed the heliopause at an orbital velocity of 17.2 km/s. Onboard hydrazine fuel reserves stand at 14.8 liters, sufficient to maintain antenna orientation toward Earth until November 2031." What is the remaining fuel volume?', '[{"text":"14.8 liters","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"17.2 km/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2031 liters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"50 liters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting specific scientific parameters and quantities from technical telemetry.', 'Scan for the phrase "fuel reserves stand at".', 1.25, -0.7, 0.25, true, 0, 'Singapore Primary 5 English'),
('ENG-56-LOC-03', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Archaeological Dig Bulletin: "Trench C revealed three distinct ceramic shards from the late Bronze Age, whereas Trench A contained exclusively iron spearheads dated to 650 BCE. Trench B has been suspended due to water seepage." Which trench yielded late Bronze Age ceramics?', '[{"text":"Trench C","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Trench A","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Trench B","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Trench D","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Matching artifact types to spatial trench identifiers in field logs.', 'Find the sentence describing "ceramic shards from the late Bronze Age".', 1.3, -0.6, 0.25, true, 0, 'Cambridge Primary Stage 5'),
('ENG-56-LOC-04', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Clean Energy Report: "While onshore wind turbines operate at an average capacity factor of 35%, offshore installations reach up to 52% owing to consistent maritime gale velocities. Solar photovoltaics in the same region average 21%." What is the capacity factor for offshore wind installations?', '[{"text":"21%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"35%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Up to 52%","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"100%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Retrieving precise comparative percentages across energy sectors.', 'Distinguish between "onshore", "offshore", and "solar".', 1.25, -0.5, 0.25, true, 0, 'US Common Core Grade 5 Informational Text'),
('ENG-56-LOC-05', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'First Aid Protocol: "In case of thermal burns: cool the affected area immediately under clean, running lukewarm water for at least 20 minutes. Do not apply ice, butter, or adhesive bandages directly to blistered skin." For how long should lukewarm water be applied?', '[{"text":"At least 20 minutes","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"5 minutes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2 hours","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Until ice is applied","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating mandatory procedural time thresholds in emergency protocols.', 'Scan for the time duration associated with "running lukewarm water".', 1.35, -0.4, 0.25, true, 0, 'Singapore Primary 6 English'),
('ENG-56-LOC-06', 'English Literacy', 'locatingInformation', '5-6', 'advanced', 'Marine Biology Field Log: "Specimen 402, a giant Pacific octopus, demonstrated tactile problem-solving by opening a childproof medicine jar in 42 seconds. Specimen 405 completed the maze navigation task in 118 seconds after three preliminary orientation runs." How quickly did Specimen 402 open the jar?', '[{"text":"3 minutes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"118 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"42 seconds","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"405 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Disentangling multiple numbered specimen IDs and distinct behavioral test times.', 'Look only at Specimen 402 and the task of opening the jar.', 1.4, -0.2, 0.25, true, 0, 'Cambridge Secondary 1 Stage 6'),
('ENG-56-LOC-07', 'English Literacy', 'locatingInformation', '5-6', 'advanced', 'Aviation Handbook: "Maximum certified ceiling for Model Skyhawk-IV is 14,000 feet Mean Sea Level (MSL). Oxygen masks must be donned by all occupants if cabin pressure exceeds an altitude equivalent of 10,000 feet for more than 30 consecutive minutes." Under what condition must oxygen masks be donned?', '[{"text":"When cabin pressure exceeds a 10,000-foot equivalent for over 30 consecutive minutes.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Whenever the aircraft climbs above 5,000 feet.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Only upon landing at airports higher than 14,000 feet MSL.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Immediately upon starting the engines before takeoff.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Retrieving multi-conditional regulatory thresholds from technical guidelines.', 'Check both the altitude threshold and the time requirement.', 1.4, 0, 0.25, true, 0, 'US Common Core Grade 6 Informational'),
('ENG-56-LOC-08', 'English Literacy', 'locatingInformation', '5-6', 'advanced', 'Deep-Sea Research Dispatch: "At the Mariana Trench (Challenger Deep, 10,928 meters), hydrostatic pressure reaches approximately 1,086 bar—over 1,000 times atmospheric pressure at sea level. Despite this, xenophyophores, giant single-celled protozoans measuring up to 20 centimeters, thrive in the abyssal sediment." What is the maximum recorded size of xenophyophores mentioned?', '[{"text":"10,928 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Up to 20 centimeters","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"1,086 bar","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"1 millimeter","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning high-density scientific abstracts for organism physical dimensions.', 'Focus on the organism "xenophyophores" and the dimension unit "centimeters".', 1.45, 0.1, 0.25, true, 0, 'Singapore Primary English Olympiad'),
('ENG-56-LOC-09', 'English Literacy', 'locatingInformation', '5-6', 'olympiad', 'Archival Treaty Summary: "Under Article VII of the 1894 Maritime Accord, coastal states retained exclusive salvage rights up to 12 nautical miles from the low-water baseline, provided formal diplomatic notice of recovery operations was submitted within 72 hours of vessel grounding." Within what timeframe must recovery notice be filed?', '[{"text":"Within 1894 hours of treaty ratification","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Within 12 days of salvage conclusion","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Within 72 hours of vessel grounding","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Immediately upon entering the 12-mile baseline","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Isolating specific compliance windows within dense legal prose.', 'Find the time constraint tied to "diplomatic notice of recovery operations".', 1.5, 0.3, 0.25, true, 0, 'Cambridge Secondary Checkpoint High Distinction'),
('ENG-56-LOC-10', 'English Literacy', 'locatingInformation', '5-6', 'olympiad', 'Bioacoustics Field Study: "Recordings in the Svalbard archipelago confirmed that male bowhead whales emit complex acoustic songs spanning frequencies from 20 Hz to 5 kHz, repeating cyclical themes every 45 to 90 seconds throughout continuous polar darkness." What is the upper acoustic frequency emitted by these bowhead whales?', '[{"text":"20 Hz","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"5 kHz (5,000 Hz)","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"90 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"45 Hz","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting upper bounds in frequency ranges from marine acoustics literature.', 'Look at the range "from 20 Hz to ...".', 1.55, 0.4, 0.25, true, 0, 'ICSE Class 6 English Language Examination')
